#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j || i + j == n - 1) {
                cout << "+";
            } else {
                cout << "-";
            }
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;
    for (int t = 0; ; t++) {
        if (n == 495) {
            cout << t << endl;
            break;
        }
        int m0 = n % 10, m1 = n / 10 % 10, m2 = n / 100;
        int tmax = 0, tmin = 0;
        if (m0 >= m1 && m1 >= m2) {
            tmax = m0 * 100 + m1 * 10 + m2;
            tmin = m2 * 100 + m1 * 10 + m0;
        } else if (m0 >= m2 && m2 >= m1) {
            tmax = m0 * 100 + m2 * 10 + m1;
            tmin = m1 * 100 + m2 * 10 + m0;
        } else if (m1 >= m0 && m0 >= m2) {
            tmax = m1 * 100 + m0 * 10 + m2;
            tmin = m2 * 100 + m0 * 10 + m1;
        } else if (m1 >= m2 && m2 >= m0) {
            tmax = m1 * 100 + m2 * 10 + m0;
            tmin = m0 * 100 + m2 * 10 + m1;
        } else if (m2 >= m0 && m0 >= m1) {
            tmax = m2 * 100 + m0 * 10 + m1;
            tmin = m1 * 100 + m0 * 10 + m2;
        } else { // m2 >= m1 && m1 >= m0
            tmax = m2 * 100 + m1 * 10 + m0;
            tmin = m0 * 100 + m1 * 10 + m2;
        }
        n = tmax - tmin;
    }
    return 0;
}
